// Parse cell address like "A1", "AA99", "Z999"
function parseAddress(addr) {
  const match = addr.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) return null
  const [, col, row] = match
  const rowNum = parseInt(row, 10)
  if (rowNum < 1 || rowNum > 999) return null
  let colNum = 0
  for (let i = 0; i < col.length; i++) {
    colNum = colNum * 26 + (col.charCodeAt(i) - 64)
  }
  if (colNum < 1 || colNum > 702) return null // Z=26, AA=27, ZZ=702
  return { col: colNum, row: rowNum }
}

// Convert col/row back to address string
function addressToString(col, row) {
  let result = ''
  while (col > 0) {
    col--
    result = String.fromCharCode(65 + (col % 26)) + result
    col = Math.floor(col / 26)
  }
  return result + row
}

