      if (word === 'TRUE') {
        tokens.push({ type: 'boolean', value: true })
      } else if (word === 'FALSE') {
        tokens.push({ type: 'boolean', value: false })
      } else if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(word)) {
        tokens.push({ type: 'function', name: word })
