    if (formula[i] === ':') {
      tokens.push({ type: 'colon' })
      i++
      continue
    }
    if (formula[i] === '(') {
      tokens.push({ type: 'lparen' })
      i++
      continue
    }
    if (formula[i] === ')') {
      tokens.push({ type: 'rparen' })
      i++
      continue
    }
    if (formula[i] === ',') {
      tokens.push({ type: 'comma' })
      i++
      continue
    }
    if (formula[i] === '^') {
      tokens.push({ type: 'power' })
      i++
      continue
    }
    if (formula[i] === '*') {
      tokens.push({ type: 'mult' })
      i++
      continue
    }
    if (formula[i] === '/') {
      tokens.push({ type: 'div' })
      i++
      continue
    }
    if (formula[i] === '+') {
      tokens.push({ type: 'plus' })
      i++
      continue
    }
    if (formula[i] === '-') {
      tokens.push({ type: 'minus' })
      i++
      continue
    }
    if (formula[i] === '=' && formula[i + 1] !== '=') {
      tokens.push({ type: 'eq' })
      i++
      continue
    }
    if (formula[i] === '<') {
      if (formula[i + 1] === '=') {
        tokens.push({ type: 'le' })
        i += 2
        continue
      }
      if (formula[i + 1] === '>') {
        tokens.push({ type: 'ne' })
        i += 2
        continue
      }
      tokens.push({ type: 'lt' })
      i++
      continue
    }
    if (formula[i] === '>') {
      if (formula[i + 1] === '=') {
        tokens.push({ type: 'ge' })
        i += 2
        continue
      }
      tokens.push({ type: 'gt' })
      i++
      continue
