  }

  parseUnary() {
    if (this.peek() && ['plus', 'minus'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parseUnary()
      if (!right) return right
      if (op.type === 'minus') {
        if (right.type === 'error') return right
        if (right.type === 'boolean') return { type: 'number', value: right.value ? -1 : 0 }
        if (right.type === 'text') return this.error('#VALUE!')
        if (right.type === 'number') return { type: 'number', value: -right.value }
      }
      return right
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.peek()
    if (!tok) return this.error('#ERR!')

    if (tok.type === 'number') {
      this.consume()
      return { type: 'number', value: tok.value }
    }

    if (tok.type === 'boolean') {
      this.consume()
      return { type: 'boolean', value: tok.value }
    }

    if (tok.type === 'address') {
      this.consume()
      // Check for range
      if (this.peek() && this.peek().type === 'colon') {
        this.consume()
        const end = this.peek()
        if (!end || end.type !== 'address') {
          return this.error('#ERR!')
        }
        this.consume()
        // Range outside function context is an error
        return this.error('#ERR!')
      }
      // Single cell
      const coord = `${tok.col},${tok.row}`
      this.deps.add(coord)
      const val = this.getCellValue(tok.col, tok.row)
