          this.consume()
        } else {
          break
        }
      }
    }

    if (!this.peek() || this.peek().type !== 'rparen') {
      return this.error('#ERR!')
    }
    this.consume()

    if (name === 'SUM') {
      if (args.length === 0) return this.error('#ERR!')
      let sum = 0
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'boolean') sum += arg.value ? 1 : 0
        else if (arg.type === 'number') sum += arg.value
        else if (arg.type === 'text') return this.error('#VALUE!')
      }
      return { type: 'number', value: sum }
    }

    if (name === 'MIN') {
      if (args.length === 0) return this.error('#ERR!')
      let min = Infinity
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'text') return this.error('#VALUE!')
        const val = arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
        if (val < min) min = val
      }
      return { type: 'number', value: min }
    }

    if (name === 'MAX') {
      if (args.length === 0) return this.error('#ERR!')
      let max = -Infinity
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'text') return this.error('#VALUE!')
        const val = arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
        if (val > max) max = val
      }
      return { type: 'number', value: max }
    }

    if (name === 'COUNT') {
      let count = 0
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'number') count++
        else if (arg.type === 'boolean') count++
      }
      return { type: 'number', value: count }
    }

    if (name === 'AVG') {
      if (args.length === 0) return this.error('#ERR!')
      let sum = 0
      let count = 0
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'text') return this.error('#VALUE!')
        sum += arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
        count++
      }
      return { type: 'number', value: sum / count }
    }

    if (name === 'ABS') {
      if (args.length !== 1) return this.error('#ERR!')
      const arg = args[0]
      if (arg.type === 'error') return arg
      if (arg.type === 'text') return this.error('#VALUE!')
      const val = arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
      return { type: 'number', value: Math.abs(val) }
    }

    if (name === 'IF') {
      if (args.length !== 3) return this.error('#ERR!')
      const cond = args[0]
      if (cond.type === 'error') return cond
      let condVal
      if (cond.type === 'boolean') {
        condVal = cond.value
      } else if (cond.type === 'number') {
