    if (formula[i] === ')') {
      tokens.push({ type: 'rparen' })
      i++
      continue
    }
    if (formula[i] === ',') {
      tokens.push({ type: 'comma' })
      i++
      continue
    }
    if (formula[i] === '^') {
      tokens.push({ type: 'power' })
      i++
      continue
    }
    if (formula[i] === '*') {
      tokens.push({ type: 'mult' })
      i++
      continue
    }
    if (formula[i] === '/') {
      tokens.push({ type: 'div' })
      i++
      continue
    }
    if (formula[i] === '+') {
      tokens.push({ type: 'plus' })
      i++
      continue
    }
    if (formula[i] === '-') {
      tokens.push({ type: 'minus' })
      i++
      continue
