// Parse and evaluate a formula
class FormulaParser {
  constructor(tokens, sheet, cellCoord) {
    this.tokens = tokens
    this.pos = 0
    this.sheet = sheet
    this.cellCoord = cellCoord
    this.deps = new Set()
    this.visiting = new Set()
  }

  error(msg) {
    return { type: 'error', value: msg }
  }

  peek() {
    return this.tokens[this.pos]
  }

  consume() {
    return this.tokens[this.pos++]
  }

  parse() {
    if (!this.tokens || this.tokens.length === 0) {
      return { type: 'number', value: 0 }
    }
    const result = this.parseComparison()
    if (this.pos < this.tokens.length) {
      return this.error('#ERR!')
    }
    return result
  }

  parseComparison() {
    let left = this.parseAddSub()
    if (!left) return left
    while (this.peek() && ['eq', 'ne', 'lt', 'le', 'gt', 'ge'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parseAddSub()
      if (!right) return right
      left = this.applyComparison(left, op.type, right)
    }
    return left
  }

  parseAddSub() {
    let left = this.parseMulDiv()
    if (!left) return left
    while (this.peek() && ['plus', 'minus'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parseMulDiv()
      if (!right) return right
      left = this.applyOp(left, op.type, right)
    }
    return left
  }

  parseMulDiv() {
    let left = this.parsePower()
    if (!left) return left
    while (this.peek() && ['mult', 'div'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parsePower()
      if (!right) return right
      left = this.applyOp(left, op.type, right)
    }
