    return left
  }

  parseUnary() {
    if (this.peek() && ['plus', 'minus'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parseUnary()
      if (!right) return right
      if (op.type === 'minus') {
        if (right.type === 'error') return right
        if (right.type === 'boolean') return { type: 'number', value: right.value ? -1 : 0 }
        if (right.type === 'text') return this.error('#VALUE!')
        if (right.type === 'number') return { type: 'number', value: -right.value }
