    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.peek()
    if (!tok) return this.error('#ERR!')

    if (tok.type === 'number') {
      this.consume()
      return { type: 'number', value: tok.value }
    }

    if (tok.type === 'boolean') {
      this.consume()
      return { type: 'boolean', value: tok.value }
    }

    if (tok.type === 'address') {
      this.consume()
      // Check for range
      if (this.peek() && this.peek().type === 'colon') {
        this.consume()
        const end = this.peek()
        if (!end || end.type !== 'address') {
          return this.error('#ERR!')
