class Sheet {
  constructor() {
    this.cells = new Map()
    this.evaluated = new Map()
  }

  addCell(address, content) {
    this.cells.set(address, new Cell(address, content, this))
  }

  getCell(address) {
    const cell = this.cells.get(address)
    if (!cell) {
      // Undeclared cell is 0
      return { type: 'number', value: 0 }
    }
    return cell.evaluate()
  }

  evaluate(address) {
    if (this.evaluated.has(address)) {
      return this.evaluated.get(address)
    }
    const cell = this.cells.get(address)
    if (!cell) {
      return { type: 'number', value: 0 }
    }
    const val = cell.evaluate()
    this.evaluated.set(address, val)
    return val
  }
}

class Cell {
  constructor(address, content, sheet) {
    this.address = address
    this.content = content
    this.sheet = sheet
    this.value = null
    this.evaluating = false
  }

  evaluate() {
    if (this.value !== null) {
      return this.value
    }

    if (this.evaluating) {
      this.value = { type: 'error', value: '#CYCLE!' }
      return this.value
    }

    this.evaluating = true

    if (this.content.startsWith('=')) {
      const formula = this.content.slice(1)
      const tokens = tokenize(formula)
      if (!tokens) {
        this.value = { type: 'error', value: '#ERR!' }
      } else {
        const parser = new FormulaParser(tokens, this.sheet, this.address)
        const result = parser.parse()
        this.value = result
      }
    } else if (this.content === '') {
      this.value = { type: 'number', value: 0 }
    } else if (/^#DIV\/0!$|^#REF!$|^#VALUE!$|^#CYCLE!$|^#NAME\?$|^#ERR!$/.test(this.content)) {
      this.value = { type: 'error', value: this.content }
    } else {
      const numMatch = this.content.match(/^-?\d+(?:\.\d+)?$/)
      if (numMatch) {
        this.value = { type: 'number', value: parseFloat(this.content) }
      } else {
        this.value = { type: 'text', value: this.content }
      }
    }

    this.evaluating = false
    return this.value
  }

  getDeps() {
    if (this.content.startsWith('=')) {
      const formula = this.content.slice(1)
      const tokens = tokenize(formula)
      if (!tokens) {
        return []
      }
      const parser = new FormulaParser(tokens, this.sheet, this.address)
      parser.parse()
      const deps = []
      for (const coord of parser.deps) {
        const [col, row] = coord.split(',').map(Number)
        deps.push({ col, row })
      }
      return deps.sort((a, b) => a.col !== b.col ? a.col - b.col : a.row - b.row)
    }
