        if (output.includes('e')) {
          output = val.value.toString()
        }
      } else if (val.type === 'error') {
        output = val.value
      } else if (val.type === 'boolean') {
        output = val.value ? 'TRUE' : 'FALSE'
      } else {
        output = val.value
      }
      console.log(`${addr}=${output}`)
