      while (j < formula.length && /[A-Z0-9]/.test(formula[j])) j++
      const word = formula.slice(i, j)
      if (word === 'TRUE') {
        tokens.push({ type: 'boolean', value: true })
      } else if (word === 'FALSE') {
        tokens.push({ type: 'boolean', value: false })
      } else if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(word)) {
        tokens.push({ type: 'function', name: word })
      } else {
        // Try to parse as address
        const addr = parseAddress(word)
        if (addr) {
          tokens.push({ type: 'address', col: addr.col, row: addr.row })
        } else {
          // Could be invalid address or range
          tokens.push({ type: 'word', value: word })
        }
      }
      i = j
      continue
    }
    // Operators and punctuation
    if (formula[i] === ':') {
      tokens.push({ type: 'colon' })
      i++
      continue
    }
    if (formula[i] === '(') {
      tokens.push({ type: 'lparen' })
      i++
      continue
    }
    if (formula[i] === ')') {
      tokens.push({ type: 'rparen' })
      i++
      continue
    }
    if (formula[i] === ',') {
      tokens.push({ type: 'comma' })
      i++
      continue
    }
    if (formula[i] === '^') {
      tokens.push({ type: 'power' })
      i++
      continue
    }
    if (formula[i] === '*') {
      tokens.push({ type: 'mult' })
      i++
      continue
    }
    if (formula[i] === '/') {
      tokens.push({ type: 'div' })
      i++
      continue
    }
    if (formula[i] === '+') {
      tokens.push({ type: 'plus' })
      i++
      continue
    }
    if (formula[i] === '-') {
      tokens.push({ type: 'minus' })
      i++
      continue
    }
    if (formula[i] === '=' && formula[i + 1] !== '=') {
      tokens.push({ type: 'eq' })
      i++
      continue
    }
    if (formula[i] === '<') {
      if (formula[i + 1] === '=') {
        tokens.push({ type: 'le' })
        i += 2
        continue
      }
      if (formula[i + 1] === '>') {
        tokens.push({ type: 'ne' })
        i += 2
        continue
      }
      tokens.push({ type: 'lt' })
      i++
      continue
    }
    if (formula[i] === '>') {
      if (formula[i + 1] === '=') {
        tokens.push({ type: 'ge' })
        i += 2
        continue
      }
      tokens.push({ type: 'gt' })
      i++
      continue
    }
    // Unknown
    return null
  }
  return tokens
}

// Parse and evaluate a formula
class FormulaParser {
  constructor(tokens, sheet, cellCoord) {
    this.tokens = tokens
    this.pos = 0
    this.sheet = sheet
    this.cellCoord = cellCoord
    this.deps = new Set()
    this.visiting = new Set()
  }

  error(msg) {
    return { type: 'error', value: msg }
  }

  peek() {
    return this.tokens[this.pos]
  }

  consume() {
    return this.tokens[this.pos++]
  }

  parse() {
    if (!this.tokens || this.tokens.length === 0) {
      return { type: 'number', value: 0 }
    }
    const result = this.parseComparison()
    if (this.pos < this.tokens.length) {
      return this.error('#ERR!')
    }
    return result
  }

  parseComparison() {
    let left = this.parseAddSub()
    if (!left) return left
    while (this.peek() && ['eq', 'ne', 'lt', 'le', 'gt', 'ge'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parseAddSub()
      if (!right) return right
      left = this.applyComparison(left, op.type, right)
    }
    return left
  }

  parseAddSub() {
    let left = this.parseMulDiv()
    if (!left) return left
    while (this.peek() && ['plus', 'minus'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parseMulDiv()
      if (!right) return right
      left = this.applyOp(left, op.type, right)
    }
    return left
  }

  parseMulDiv() {
    let left = this.parsePower()
    if (!left) return left
    while (this.peek() && ['mult', 'div'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parsePower()
      if (!right) return right
      left = this.applyOp(left, op.type, right)
    }
    return left
  }

  parsePower() {
    let left = this.parseUnary()
    if (!left) return left
    if (this.peek() && this.peek().type === 'power') {
      const op = this.consume()
      const right = this.parsePower() // Right associative
      if (!right) return right
      left = this.applyOp(left, op.type, right)
    }
    return left
  }

  parseUnary() {
    if (this.peek() && ['plus', 'minus'].includes(this.peek().type)) {
      const op = this.consume()
      const right = this.parseUnary()
      if (!right) return right
      if (op.type === 'minus') {
        if (right.type === 'error') return right
        if (right.type === 'boolean') return { type: 'number', value: right.value ? -1 : 0 }
        if (right.type === 'text') return this.error('#VALUE!')
        if (right.type === 'number') return { type: 'number', value: -right.value }
      }
      return right
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.peek()
    if (!tok) return this.error('#ERR!')

    if (tok.type === 'number') {
      this.consume()
      return { type: 'number', value: tok.value }
    }

    if (tok.type === 'boolean') {
      this.consume()
      return { type: 'boolean', value: tok.value }
    }

    if (tok.type === 'address') {
      this.consume()
      // Check for range
      if (this.peek() && this.peek().type === 'colon') {
        this.consume()
        const end = this.peek()
        if (!end || end.type !== 'address') {
          return this.error('#ERR!')
        }
        this.consume()
        // Range outside function context is an error
        return this.error('#ERR!')
      }
      // Single cell
      const coord = `${tok.col},${tok.row}`
      this.deps.add(coord)
      const val = this.getCellValue(tok.col, tok.row)
      return val
    }

    if (tok.type === 'word') {
      // This is an invalid address or word
      this.consume()
      return this.error('#ERR!')
    }

    if (tok.type === 'lparen') {
      this.consume()
      const val = this.parseComparison()
      if (!val) return val
      if (!this.peek() || this.peek().type !== 'rparen') {
        return this.error('#ERR!')
      }
      this.consume()
      return val
    }

    if (tok.type === 'function') {
      const funcName = tok.name
      this.consume()
      if (!this.peek() || this.peek().type !== 'lparen') {
        return this.error('#ERR!')
      }
      this.consume()
      return this.parseFunction(funcName)
    }

    return this.error('#ERR!')
  }

  parseFunction(name) {
    const args = []

    if (this.peek() && this.peek().type !== 'rparen') {
      while (true) {
        const arg = this.parseFunctionArg()
        if (!arg) return arg
        args.push(arg)
        if (this.peek() && this.peek().type === 'comma') {
          this.consume()
        } else {
          break
        }
      }
    }

    if (!this.peek() || this.peek().type !== 'rparen') {
      return this.error('#ERR!')
    }
    this.consume()

    if (name === 'SUM') {
      if (args.length === 0) return this.error('#ERR!')
      let sum = 0
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'boolean') sum += arg.value ? 1 : 0
        else if (arg.type === 'number') sum += arg.value
        else if (arg.type === 'text') return this.error('#VALUE!')
      }
      return { type: 'number', value: sum }
    }

    if (name === 'MIN') {
      if (args.length === 0) return this.error('#ERR!')
      let min = Infinity
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'text') return this.error('#VALUE!')
        const val = arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
        if (val < min) min = val
      }
      return { type: 'number', value: min }
    }

    if (name === 'MAX') {
      if (args.length === 0) return this.error('#ERR!')
      let max = -Infinity
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'text') return this.error('#VALUE!')
        const val = arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
        if (val > max) max = val
      }
      return { type: 'number', value: max }
    }

    if (name === 'COUNT') {
      let count = 0
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'number') count++
        else if (arg.type === 'boolean') count++
      }
      return { type: 'number', value: count }
    }

    if (name === 'AVG') {
      if (args.length === 0) return this.error('#ERR!')
      let sum = 0
      let count = 0
      for (const arg of args) {
        if (arg.type === 'error') return arg
        if (arg.type === 'text') return this.error('#VALUE!')
        sum += arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
        count++
      }
      return { type: 'number', value: sum / count }
    }

    if (name === 'ABS') {
      if (args.length !== 1) return this.error('#ERR!')
      const arg = args[0]
      if (arg.type === 'error') return arg
      if (arg.type === 'text') return this.error('#VALUE!')
      const val = arg.type === 'boolean' ? (arg.value ? 1 : 0) : arg.value
      return { type: 'number', value: Math.abs(val) }
    }

    if (name === 'IF') {
      if (args.length !== 3) return this.error('#ERR!')
      const cond = args[0]
      if (cond.type === 'error') return cond
      let condVal
      if (cond.type === 'boolean') {
        condVal = cond.value
      } else if (cond.type === 'number') {
        condVal = cond.value !== 0
      } else {
        return this.error('#VALUE!')
      }
      return condVal ? args[1] : args[2]
    }

    return this.error('#NAME?')
  }

  parseFunctionArg() {
    // In a function context, we can have ranges
    const startPos = this.pos
    const start = this.peek()
    if (!start || start.type !== 'address') {
      // Not a range, parse normally
      return this.parseComparison()
    }

    this.consume()
    if (this.peek() && this.peek().type === 'colon') {
      // This is a range
      this.consume()
      const end = this.peek()
      if (!end || end.type !== 'address') {
        return this.error('#ERR!')
      }
      this.consume()
      // Expand range
      const cells = this.expandRange(start.col, start.row, end.col, end.row)
      return { type: 'range', cells }
    }

    // Single cell in function context
    const coord = `${start.col},${start.row}`
    this.deps.add(coord)
    return this.getCellValue(start.col, start.row)
  }

  expandRange(col1, row1, col2, row2) {
    const result = []
    const minCol = Math.min(col1, col2)
    const maxCol = Math.max(col1, col2)
    const minRow = Math.min(row1, row2)
    const maxRow = Math.max(row1, row2)
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        result.push({ col: c, row: r })
      }
    }
    return result
  }

  getCellValue(col, row) {
    const addr = addressToString(col, row)
    const parsed = parseAddress(addr)
    if (!parsed) {
      return this.error('#REF!')
    }

    const cell = this.sheet.cells.get(addr)
    if (!cell) {
      return { type: 'number', value: 0 }
    }

    // Check for cycle
    const coord = `${col},${row}`
    if (this.visiting.has(coord)) {
      return this.error('#CYCLE!')
    }

    this.visiting.add(coord)
    const val = cell.evaluate()
    this.visiting.delete(coord)

    return val
  }

  applyOp(left, op, right) {
    if (left.type === 'error') return left
    if (right.type === 'error') return right

    if (op === 'plus') {
      const lv = this.toNumber(left)
      if (lv === null) return this.error('#VALUE!')
      const rv = this.toNumber(right)
      if (rv === null) return this.error('#VALUE!')
      return { type: 'number', value: lv + rv }
    }

    if (op === 'minus') {
      const lv = this.toNumber(left)
      if (lv === null) return this.error('#VALUE!')
      const rv = this.toNumber(right)
      if (rv === null) return this.error('#VALUE!')
      return { type: 'number', value: lv - rv }
    }

    if (op === 'mult') {
      const lv = this.toNumber(left)
      if (lv === null) return this.error('#VALUE!')
      const rv = this.toNumber(right)
      if (rv === null) return this.error('#VALUE!')
      return { type: 'number', value: lv * rv }
    }

    if (op === 'div') {
      const lv = this.toNumber(left)
      if (lv === null) return this.error('#VALUE!')
      const rv = this.toNumber(right)
      if (rv === null) return this.error('#VALUE!')
      if (rv === 0) return this.error('#DIV/0!')
      const result = lv / rv
      if (!isFinite(result)) return this.error('#DIV/0!')
      return { type: 'number', value: result }
    }

    if (op === 'power') {
      const lv = this.toNumber(left)
      if (lv === null) return this.error('#VALUE!')
      const rv = this.toNumber(right)
      if (rv === null) return this.error('#VALUE!')
      const result = Math.pow(lv, rv)
      if (!isFinite(result)) return this.error('#DIV/0!')
      return { type: 'number', value: result }
    }

    return this.error('#ERR!')
  }

  applyComparison(left, op, right) {
    if (left.type === 'error') return left
    if (right.type === 'error') return right

    let cmp = 0
    if (left.type === 'number' && right.type === 'number') {
      cmp = left.value < right.value ? -1 : left.value > right.value ? 1 : 0
    } else if (left.type === 'text' && right.type === 'text') {
      cmp = left.value < right.value ? -1 : left.value > right.value ? 1 : 0
    } else if (left.type === 'boolean' && right.type === 'boolean') {
      cmp = (left.value ? 1 : 0) < (right.value ? 1 : 0) ? -1 : (left.value ? 1 : 0) > (right.value ? 1 : 0) ? 1 : 0
    } else {
      // Cross-type comparison: number < text < boolean
      const leftOrder = left.type === 'number' ? 0 : left.type === 'text' ? 1 : 2
      const rightOrder = right.type === 'number' ? 0 : right.type === 'text' ? 1 : 2
      cmp = leftOrder < rightOrder ? -1 : leftOrder > rightOrder ? 1 : 0
    }

    let result
    switch (op) {
      case 'eq': result = cmp === 0; break
      case 'ne': result = cmp !== 0; break
      case 'lt': result = cmp < 0; break
      case 'le': result = cmp <= 0; break
      case 'gt': result = cmp > 0; break
      case 'ge': result = cmp >= 0; break
      default: return this.error('#ERR!')
    }
    return { type: 'boolean', value: result }
  }

  toNumber(val) {
    if (val.type === 'number') return val.value
    if (val.type === 'boolean') return val.value ? 1 : 0
    return null
  }
}

class Sheet {
  constructor() {
    this.cells = new Map()
    this.evaluated = new Map()
  }

  addCell(address, content) {
    this.cells.set(address, new Cell(address, content, this))
  }

  getCell(address) {
    const cell = this.cells.get(address)
    if (!cell) {
      // Undeclared cell is 0
      return { type: 'number', value: 0 }
    }
    return cell.evaluate()
  }

  evaluate(address) {
    if (this.evaluated.has(address)) {
      return this.evaluated.get(address)
    }
    const cell = this.cells.get(address)
    if (!cell) {
      return { type: 'number', value: 0 }
    }
    const val = cell.evaluate()
    this.evaluated.set(address, val)
    return val
  }
}

class Cell {
  constructor(address, content, sheet) {
    this.address = address
    this.content = content
    this.sheet = sheet
    this.value = null
    this.evaluating = false
  }

  evaluate() {
    if (this.value !== null) {
      return this.value
    }

    if (this.evaluating) {
      this.value = { type: 'error', value: '#CYCLE!' }
      return this.value
    }

    this.evaluating = true

    if (this.content.startsWith('=')) {
      const formula = this.content.slice(1)
      const tokens = tokenize(formula)
      if (!tokens) {
        this.value = { type: 'error', value: '#ERR!' }
      } else {
        const parser = new FormulaParser(tokens, this.sheet, this.address)
        const result = parser.parse()
        this.value = result
      }
    } else if (this.content === '') {
      this.value = { type: 'number', value: 0 }
    } else if (/^#DIV\/0!$|^#REF!$|^#VALUE!$|^#CYCLE!$|^#NAME\?$|^#ERR!$/.test(this.content)) {
      this.value = { type: 'error', value: this.content }
    } else {
      const numMatch = this.content.match(/^-?\d+(?:\.\d+)?$/)
      if (numMatch) {
        this.value = { type: 'number', value: parseFloat(this.content) }
      } else {
        this.value = { type: 'text', value: this.content }
      }
    }

    this.evaluating = false
    return this.value
  }

  getDeps() {
    if (this.content.startsWith('=')) {
      const formula = this.content.slice(1)
      const tokens = tokenize(formula)
      if (!tokens) {
        return []
      }
      const parser = new FormulaParser(tokens, this.sheet, this.address)
      parser.parse()
      const deps = []
      for (const coord of parser.deps) {
        const [col, row] = coord.split(',').map(Number)
        deps.push({ col, row })
      }
      return deps.sort((a, b) => a.col !== b.col ? a.col - b.col : a.row - b.row)
    }
    return []
  }
}

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['values', 'deps'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read stdin
  let input = ''
  for await (const chunk of stdin) {
    input += chunk.toString()
  }

  const lines = input.split('\n')
  // Drop empty tail
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const sheet = new Sheet()
  const cellAddresses = []

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    let line = lines[lineNum]
    // Strip leading spaces and tabs
    line = line.replace(/^[ \t]+/, '')
    // Ignore empty lines or lines starting with #
    if (line === '' || line.startsWith('#')) {
      continue
    }

    // Parse address
    const spaceMatch = line.match(/^([^\s]+)([ \t].*)$/)
    let address, content
    if (spaceMatch) {
      address = spaceMatch[1]
      content = spaceMatch[2].replace(/^[ \t]+/, '')
    } else {
      address = line
      content = ''
    }

    // Validate address
    const parsed = parseAddress(address.toUpperCase())
    if (!parsed) {
      process.stderr.write(`error: line ${lineNum + 1}: invalid cell address ${address}\n`)
      process.exit(2)
    }

    const upperAddr = address.toUpperCase()
    if (sheet.cells.has(upperAddr)) {
      process.stderr.write(`error: line ${lineNum + 1}: cell ${upperAddr} is declared twice\n`)
      process.exit(2)
    }

    sheet.addCell(upperAddr, content)
    cellAddresses.push(upperAddr)
  }

  // Sort addresses by column then row
  const sorted = Array.from(sheet.cells.keys()).sort((a, b) => {
    const pa = parseAddress(a)
    const pb = parseAddress(b)
    if (pa.col !== pb.col) return pa.col - pb.col
    return pa.row - pb.row
  })

  if (mode === 'values') {
    for (const addr of sorted) {
      const val = sheet.evaluate(addr)
      let output
      if (val.type === 'number') {
        output = val.value.toPrecision(10).replace(/\.?0+$/, '')
        if (output.includes('e')) {
          output = val.value.toString()
        }
      } else if (val.type === 'error') {
        output = val.value
      } else if (val.type === 'boolean') {
        output = val.value ? 'TRUE' : 'FALSE'
      } else {
        output = val.value
      }
      console.log(`${addr}=${output}`)
    }
  } else {
    // deps mode
    for (const addr of sorted) {
      const cell = sheet.cells.get(addr)
      const deps = cell.getDeps()
      const depStrs = deps.map(d => addressToString(d.col, d.row))
      if (depStrs.length === 0) {
        console.log(`${addr}:`)
      } else {
        console.log(`${addr}: ${depStrs.join(' ')}`)
      }
    }
  }

  process.exit(0)
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})
"}

