#!/usr/bin/env node

import { createReadStream } from 'fs'
import { stdin } from 'process'

// Parse cell address like "A1", "AA99", "Z999"
function parseAddress(addr) {
  const match = addr.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) return null
  const [, col, row] = match
  const rowNum = parseInt(row, 10)
  if (rowNum < 1 || rowNum > 999) return null
  let colNum = 0
  for (let i = 0; i < col.length; i++) {
    colNum = colNum * 26 + (col.charCodeAt(i) - 64)
  }
  if (colNum < 1 || colNum > 702) return null // Z=26, AA=27, ZZ=702
  return { col: colNum, row: rowNum }
}

// Convert col/row back to address string
function addressToString(col, row) {
  let result = ''
  while (col > 0) {
    col--
    result = String.fromCharCode(65 + (col % 26)) + result
    col = Math.floor(col / 26)
  }
  return result + row
}

// Tokenize a formula
function tokenize(formula) {
  const tokens = []
  let i = 0
  while (i < formula.length) {
    // Skip whitespace
    if (/\s/.test(formula[i])) {
      i++
      continue
    }
    // Numbers
    if (/\d/.test(formula[i])) {
      let j = i
      while (j < formula.length && /[\d.]/.test(formula[j])) j++
      tokens.push({ type: 'number', value: parseFloat(formula.slice(i, j)) })
      i = j
      continue
    }
    // Cell addresses or keywords (A1, AA1, TRUE, FALSE, function names)
    if (/[A-Z]/.test(formula[i])) {
      let j = i
      while (j < formula.length && /[A-Z0-9]/.test(formula[j])) j++
      const word = formula.slice(i, j)
      if (word === 'TRUE') {
        tokens.push({ type: 'boolean', value: true })
      } else if (word === 'FALSE') {
        tokens.push({ type: 'boolean', value: false })
      } else if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(word)) {
        tokens.push({ type: 'function', name: word })
      } else {
        // Try to parse as address
        const addr = parseAddress(word)
        if (addr) {
          tokens.push({ type: 'address', col: addr.col, row: addr.row })
        } else {
          // Could be invalid address or range
          tokens.push({ type: 'word', value: word })
        }
      }
      i = j
      continue
    }
    // Operators and punctuation
    if (formula[i] === ':') {
      tokens.push({ type: 'colon' })
      i++
      continue
    }
    if (formula[i] === '(') {
